'use strict';
const {course}=require('./data-wave2-helper');
const specs=[
{id:'pd-load',comps:['m1.c1'],title:'Load a small table and select rows with labels or positions',intro:'A stock analyst receives a CSV extract with product codes and quantities. A DataFrame is a labeled two-dimensional table; safe selection starts by deciding whether a selector refers to labels or physical positions.',sections:[['Load with an explicit interpretation contract','read_csv parses a delimited source, but inferred dtypes may not match business meaning. Product codes such as 001 are identifiers, not integers to average. Declare important dtypes, missing markers and date handling where appropriate, then inspect columns, shape and sample values. A successful parse is not a completeness or correctness guarantee.','Use synthetic StringIO sources in examples to isolate parsing from filesystem and network assumptions. For real extracts, record source versions, encoding, delimiter and expected schema. A surprising row count or unexpected missing values should be investigated before analysis.'],['loc is label-based; iloc is position-based','loc selects index/column labels and can use a compatible Boolean mask. A label slice includes its stop label when the index supports that slice. iloc selects zero-based positions; its slice stop is exclusive, like ordinary Python. Integer index labels are still labels under loc rather than positions.','Select needed columns explicitly, verify expected rows and use .loc for a direct assignment to the intended DataFrame. Chained indexing may operate on a temporary object and can behave differently with copy-on-write settings. The example only reads data and demonstrates the distinction using a deliberately nondefault index.']],problem:'Preserve string product codes and compare label selection with positional selection.',steps:['Read a synthetic CSV with a declared string code dtype.','Set an explicit index and select a label range.','Select a positional range and compare row identities.'],code:'import pandas as pd\nfrom io import StringIO\ndf=pd.read_csv(StringIO("code,qty\\n001,2\\n002,5\\n003,1\\n"),dtype={"code":"string"})\ndf.index=[10,20,30]\nprint(df.loc[10:20,"code"].tolist())\nprint(df.iloc[0:1,0].tolist())\nprint(pd.__version__)',expect:"['001', '002']\n['001']\n2.2.3",limit:'The fixture verifies pandas2.2.3 parsing and selector semantics on an ordered unique index. Real file access, duplicate labels and other index types require their own checks.',mistakes:['An integer index label is not automatically a row position.','Type inference can strip meaningful leading zeros from identifiers.'],takeaways:['Preserve identifier semantics during loading.','Choose label or position selection deliberately.'],practice:[
['Which accessor uses zero-based row positions?','iloc','loc always','groupby','merge','iloc uses physical integer positions; loc interprets index labels.'],
['A loc label slice 10:20 on this fixture includes which labels?','10 and 20','Only 10','Only 20','Neither label','Label-based slicing includes the stop label for this ordered-index fixture.'],
['How should a code 001 be preserved as an identifier?','Declare a string dtype','Average it as a number','Sort it into an integer','Drop its leading zeros','A string representation preserves meaningful identifier formatting that integer inference can erase.'],
['A warehouse uses loc[0] after setting index labels 10,20,30. What is wrong?','Zero is not an index label','loc always means first row','The table must be empty','Quantities cannot be selected','loc requests a label; the first physical row would be selected with iloc[0].'],
['A parsed CSV has unexpected columns. What should happen before aggregation?','Validate the schema','Ignore extra columns always','Trust parse success alone','Rename columns randomly','Parsing only establishes readability; the expected business schema still needs explicit verification.'],
['A developer uses iloc[0:2]. How many fixture rows are selected?','Two rows','Three rows','One row','No rows','Positional slice stop two is exclusive, selecting positions zero and one.'],
['A chained selection is used to update inventory. What is preferable?','A direct loc assignment','An unreviewed temporary slice','Renaming the warning','Assuming every view writes through','A single explicit loc assignment targets the intended object and avoids ambiguous chained-assignment behavior.']
],formal:[
['What is a DataFrame?','A labeled 2D table','An unordered scalar','Only a filesystem path','A mandatory SQL server','A DataFrame organizes rows and columns with labels and column dtypes.'],
['What determines loc row selection?','Index labels','Only physical row positions','Column memory size','Group aggregation order','loc is label-oriented, including integer labels when those are present.'],
['Which slicing convention applies to iloc stop positions?','Stop is excluded','Stop is always included','Both endpoints are excluded','Every stop selects all rows','iloc follows positional half-open slicing with an exclusive stop.'],
['A retailer imports postal code 0007 and sees 7. What should be revised?','Identifier parsing dtype','The count of orders','Only report font','The row sort direction','A string dtype preserves formatting meaningful to an identifier.'],
['A support table has index labels 5 and 9. What does iloc[1] select?','The second physical row','The row with label one','The row with label five','Every row after label one','iloc positions are independent of the stored index labels.'],
['A batch loads without exceptions but has half the expected records. What does parse success prove?','Only that parsing succeeded','Complete source coverage','Correct business totals','Correct causal conclusions','Schema, counts, missingness and source completeness remain separate validation concerns.'],
['A user-supplied CSV changes a quantity column to text. What should analysis do?','Check types and schema','Silently trust old arithmetic','Drop every text row secretly','Interpret all text as zero','A consumer must validate the actual loaded representation before using numeric operations.'],
['A notebook updates df[df.qty>0]["qty"] and expects a permanent change. What should be reviewed?','Chained-assignment semantics','Only the output title','Only the CSV separator','Only the row-count display','Chained operations can target a temporary object; explicit assignment to df.loc is clearer and more reliable.'],
['A label slice is applied to an unsorted or nonunique index. What is appropriate?','Check that index’s slicing behavior','Assume all indices behave identically','Replace every label by a position','Ignore any selection errors','The lesson’s ordered-unique-index example does not establish every index type’s selection behavior.'],
['A pipeline switches from default RangeIndex to customer ids. What should selector tests protect?','Label/position intent','Only column order','Only file extension','Only the chart color','Changing labels can alter loc behavior while iloc remains positional, so tests should bind the intended semantics.']
]},
{id:'pd-types',comps:['m1.c2'],title:'Inspect nullable dtypes and memory without losing meaning',intro:'A customer table contains optional ages and repeated region labels. Choosing a dtype affects missing-value behavior, arithmetic and memory use, but a smaller representation must still preserve the data’s meaning.',sections:[['Inspect before converting','Use dtypes and info to examine columns, null counts and memory estimates. pandas supports nullable extension dtypes such as Int64 and string; the capitalized nullable Int64 differs from NumPy int64 because it can represent missing values through pd.NA. Dtype names and values need explicit review after loading.','astype converts according to a target type but can fail when values are incompatible. to_numeric with errors="coerce" marks unparseable values as missing, which must be counted and explained rather than silently treated as valid zero. A successful conversion does not validate units or domain constraints.'],['Memory is a property to measure, not a reason to corrupt data','memory_usage(deep=True) includes deeper object memory estimates, useful for string-heavy columns. Exact bytes vary with versions and representations. Categories can reduce repeated-string storage and define allowed categories, but high-cardinality identifiers may not benefit. Downcasting numeric values requires range/precision checks.','The worked example contrasts nullable integer behavior with a parsing failure flag and checks that deep object memory is at least the shallow estimate. It avoids asserting platform-specific byte counts. The sample is not a benchmark and does not justify an untested dtype policy for every dataset.']],problem:'Inspect nullable ages, detect a failed numeric parse and compare memory estimates.',steps:['Create an explicitly nullable integer column.','Convert numeric text while counting newly missing values.','Compare deep and shallow object memory estimates.'],code:'import pandas as pd\nage=pd.Series([20,None,35],dtype="Int64")\nparsed=pd.to_numeric(pd.Series(["3","bad","5"]),errors="coerce")\nlabels=pd.Series(["north-region"*10]*3,dtype=object)\nprint(str(age.dtype),int(age.isna().sum()))\nprint(int(parsed.isna().sum()))\nprint(labels.memory_usage(deep=True)>=labels.memory_usage(deep=False))',expect:'Int64 1\n1\nTrue',limit:'The checks establish declared dtype/null behavior and a memory-estimate relationship in pandas2.2.3. They do not measure peak process memory or approve data-lossy conversions.',mistakes:['Coerced parsing errors are new missingness, not repaired measurements.','A memory reduction is unacceptable if it changes identifier, unit or precision meaning.'],takeaways:['Choose nullable representations consciously.','Measure memory and validate conversion effects.'],practice:[
['Which pandas dtype can hold integer values with pd.NA?','Nullable Int64','Only plain int64','Only bool','Only a file path','The extension dtype Int64 supports missing integers, unlike the ordinary NumPy integer dtype.'],
['What can errors="coerce" do in to_numeric?','Create missing on failure','Prove every value valid','Convert every error to zero','Preserve invalid text as numeric','Coercion replaces unparseable entries with missing markers, so the resulting loss must be inspected.'],
['Which memory option includes deeper object estimates?','deep=True','deep=False always','sort=True','dropna=False','deep=True accounts more fully for memory associated with object values such as strings.'],
['A code column is downcast to integers and loses leading zeros. What was sacrificed?','Identifier meaning','Only memory reporting','Only row count','Only a warning label','Representation changes must preserve business semantics, not merely save bytes.'],
['A tiny memory benchmark is used to mandate categories for unique ids. What should be checked?','Real cardinality and semantics','Only the sample filename','Only whether ids are strings','Only export speed','Category overhead/benefits depend on repetition and usage; unique identifiers may not benefit.'],
['A conversion creates 400 extra nulls. What must be reported?','Parsing-loss coverage','Only the final average','That conversion fixed all values','Only the dtype name','New missingness can change downstream populations and metrics and must be investigated.'],
['An amount downcast loses fractional cents needed by the policy. What is required?','A precision-preserving type','Only more printed digits','Only a larger row id','Only reordering columns','Storage optimization must respect the required numeric precision and business calculation rules.']
],formal:[
['What does df.dtypes reveal?','Column representations','Every business rule','Source completeness','All row identities','Dtypes describe how values are represented and operated on, not every semantic or collection property.'],
['What should follow a lossy numeric coercion?','A parse-failure review','Automatic zero imputation','A guaranteed accuracy claim','Deletion of all raw text','Coercion exposes invalid representations as missing; it does not establish the correct intended values.'],
['Does a smaller dtype guarantee a better analytical representation?','No','Yes universally','Only for identifiers','Only for monetary columns','Meaning, range and precision must be preserved alongside memory considerations.'],
['A customer age column has missing entries. Why might nullable Int64 be chosen?','Nullable integer meaning','Automatic age accuracy','Guaranteed causal relevance','No need for validation','The extension dtype retains integer values while representing missingness explicitly.'],
['A long-text column reports far more memory with deep=True. What is a likely explanation?','String memory is included','More rows were invented','The dtype became a matrix','Every value was duplicated','Shallow object memory may omit the deeper referenced objects counted by the deep estimate.'],
['A dataset has almost unique free-text ids. What should precede category conversion?','A measured suitability check','Automatic category adoption','Deletion of rare ids','An assumed memory guarantee','Categorical storage benefits depend on cardinality and operations and should be measured on representative data.'],
['An analyst assumes a numeric dtype means all amounts are in dollars. What is missing?','The unit contract','Only a larger memory estimate','Only a column index','Only integer arithmetic','Dtypes encode representation, not currency/unit meaning.'],
['A pipeline stores very large counts in a small integer representation. What must be validated?','Range and overflow','Only chart labels','Only CSV row order','Only source filenames','Downcasting needs a range policy so valid magnitudes are not overflowed or rejected unexpectedly.'],
['A parsing step drops invalid values before calculating a rate. What is at risk?','The represented denominator','Only the output extension','Only report orientation','Only the column heading','Unreported conversion loss can change the analyzed population and bias the resulting rate.'],
['A memory report is used as a peak-RAM guarantee for production. What limitation matters?','It is not full process peak memory','It proves every allocation','It includes all future workloads','It eliminates temporary copies','Column memory estimates do not account for every runtime object, intermediate or workload peak.']
]},
{id:'pd-alignment',comps:['m1.c1','m1.c2'],title:'Understand index alignment and make selections auditable',intro:'pandas often aligns data by labels rather than blindly pairing physical positions. This protects meaning when labels are correct, but can create surprising missing values when a developer assumes positional arithmetic.',sections:[['Alignment is a semantic operation','When two Series are added, pandas aligns matching index labels. A label present in only one operand generally produces a missing result for ordinary addition unless a deliberate fill policy is applied. Reordering one Series does not change label-based pairing.','An index can be nonunique. Duplicate labels can change selection and arithmetic behavior, so a one-row-per-entity contract should test uniqueness explicitly. Resetting an index changes labels; it does not deduplicate records or justify discarding identity meaning.'],['Masks and assignments need the intended target','Boolean masks built from the same DataFrame align naturally. A mask from another differently indexed object can align, warn or fail depending on its relationship to the target. Do not treat an arbitrary same-length Boolean Series as automatically position-based. Use deliberate positional arrays only when positional semantics are truly intended.','The fixture adds two differently ordered Series and exposes one unmatched label. It then checks index uniqueness. The result illustrates default alignment, not a universal policy that missing counterpart values should be filled with zero.']],problem:'Observe matching-label arithmetic and detect an unmatched entity.',steps:['Create two Series with overlapping labels in different order.','Add them and inspect matched and unmatched positions.','Check whether the result’s index satisfies a uniqueness contract.'],code:'import pandas as pd\na=pd.Series([10,20],index=["a","b"])\nb=pd.Series([3,2],index=["b","c"])\nz=a+b\nprint(z.loc["b"])\nprint(z.isna().to_dict())\nprint(z.index.is_unique)',expect:"23.0\n{'a': True, 'b': False, 'c': True}\nTrue",limit:'These outputs verify default Series alignment on unique string labels. Duplicate indexes, fill policies and other operations require explicit tests.',mistakes:['Same length does not mean two labeled Series pair positionally.','Resetting labels is not proof that entity identity or row uniqueness is correct.'],takeaways:['Treat index labels as part of data meaning.','Audit alignment, unmatched labels and uniqueness.'],practice:[
['How do ordinary Series additions pair values by default?','Matching index labels','Only physical positions','Column memory size','Alphabetical value order','pandas aligns Series operands on their index labels before arithmetic.'],
['What can an unmatched label produce in ordinary addition?','A missing result','A guaranteed zero','A new valid measurement','An automatic duplicate removal','Without a counterpart, ordinary aligned addition generally yields a missing value.'],
['Does reset_index remove duplicate business records?','No','Yes universally','Only for numeric labels','Only with string labels','Changing/resetting labels is separate from deduplicating entities or events.'],
['Two financial Series are reordered differently but keep correct unique account labels. What preserves pairing?','Label alignment','The old row positions','Only equal length','Only shared dtype','Matching account labels determines corresponding values despite different physical orders.'],
['A Boolean mask comes from a different index. What must be reviewed?','Mask/target alignment','Only mask length','Only variable name length','Only the output title','A Boolean Series can align by label, so its relationship to the target index matters.'],
['A table promises one row per account. Which property helps test that promise?','Index/key uniqueness','Only column count','Only numeric dtype','Only CSV file size','Unique account labels or keys are necessary for a one-row-per-account representation.'],
['A developer fills every unmatched value with zero. What is required?','A justified fill policy','Only a shorter expression','Only matching row counts','Only a new label','Zero is a substantive value; an absent counterpart is not automatically a measured zero.']
],formal:[
['What is index alignment?','Pairing values through labels','Sorting every value numerically','Removing every duplicate','Converting labels to positions','Alignment matches labeled axes for supported operations rather than relying solely on order.'],
['Can a Series index contain duplicate labels?','Yes','No by construction','Only if values are missing','Only for integers','pandas permits nonunique indexes, so applications must enforce uniqueness where their contract requires it.'],
['What does index.is_unique test?','Whether labels repeat','Whether values are accurate','Whether all rows are independent','Whether units match','It checks label uniqueness, not semantic correctness, independence or units.'],
['A sales Series and a costs Series have equal length but different account labels. What should an analyst inspect?','Unmatched-label meaning','Only the first value','Only the shared dtype','Only row-count equality','Equal size does not establish aligned entities; default arithmetic can introduce missing values for unmatched labels.'],
['A masking step selects the wrong customers after index changes. Which test targets the issue?','Expected identities','Only selected row count','Only output numeric type','Only memory usage','Identity assertions detect wrong membership even when the resulting count happens to match.'],
['A reset_index call makes two tables share labels 0,1,2. Does that prove records correspond?','No, entity order may differ','Yes, equal labels create identity','Only if values are positive','Only if columns are sorted','New positional labels can align unrelated entities unless record identity/order is deliberately established.'],
['An analyst fills missing matched costs with zero to raise margins. What is wrong?','An unjustified assumption','A necessary alignment rule','A guaranteed accuracy repair','Only a formatting issue','Absent costs are not automatically zero; the policy can materially bias profit calculations.'],
['A company expects unique customer keys but finds repeats. What should happen before arithmetic?','Resolve grain and keys','Ignore duplicates silently','Average the customer ids','Rename the index only','Repeated identities can change alignment and aggregation; the intended entity grain must be restored or documented.'],
['A row-count check passes after a filter but the wrong users remain. What was insufficient?','Count-only validation','The concept of filtering','Every label-based accessor','The DataFrame’s existence','Membership/identity tests are needed because many different subsets can have the same size.'],
['A developer converts a mask to an unlabeled array to avoid alignment. What must be explicit?','The intended positional contract','That labels never matter','That every row is correct','That missing values are zero','Removing labels changes semantics; positional pairing is appropriate only when order correspondence is deliberately guaranteed.']
]},
{id:'pd-group',comps:['m2.c1'],title:'Group records and choose aggregations with explicit null behavior',intro:'A retailer wants units and observed prices per region. Grouping defines which rows belong together; aggregation defines which information is retained and what missing values mean.',sections:[['Split, apply and combine with a declared grain','groupby partitions rows by one or more keys and produces summaries such as sum, mean, size or count. size counts rows; count counts nonmissing values per column. These differ when values are missing. Named aggregation makes output meanings explicit rather than relying on opaque generated labels.','By default, missing grouping keys are excluded in common groupby operations; dropna=False retains a missing-key group. Decide whether that group belongs in the target population and report it deliberately. Categorical keys also involve observed-category behavior that should be specified for stable output across versions.'],['A summary loses row-level information','Grouping changes grain: one row per region is not one row per transaction. An average-of-averages needs denominator weights if it is intended to recover an overall mean. Preserve raw evidence separately and include counts so reviewers can see varying group support.','The fixture contrasts size with count and retains a missing region explicitly. It verifies pandas defaults/options under a small dataset; it does not establish that missing regions are ignorable or that all groups are comparable.']],problem:'Summarize units while exposing missing measures and missing grouping keys.',steps:['Create explicit region and units columns.','Group with dropna=False so unassigned regions remain visible.','Compare row count, observed-value count and sum.'],code:'import pandas as pd\ndf=pd.DataFrame({"region":["n","n",None],"units":[2,None,5]})\ng=df.groupby("region",dropna=False)["units"].agg(["size","count","sum"])\nprint(g.loc["n"].tolist())\nprint(int(g["size"].sum()))',expect:'[2.0, 1.0, 2.0]\n3',limit:'The group output retains all three fixture rows but the sum’s missing-value handling is not a universal business policy for unknown quantities.',mistakes:['count and size are not interchangeable when values are missing.','Grouping drops detail and changes the output grain.'],takeaways:['Name aggregations and preserve supporting counts.','Specify missing-key and missing-value behavior.'],practice:[
['Which group operation counts every row?','size','count always','mean','median','Group size includes rows regardless of missing values in a particular measure column.'],
['What does count count for a selected column?','Nonmissing values','Every row always','Only positive values','Unique ids only','count excludes missing values in the counted column.'],
['Which option retains a missing grouping key as a group?','dropna=False','dropna=True','ignore_index=True','validate="one_to_one"','dropna=False keeps a missing-key group rather than excluding those rows.'],
['A region has two rows but one units value is missing. What distinguishes size and count?','Two rows, one known value','Both must be two','Both must be one','Only one returns a number','The group contains two observations but only one nonmissing measurement.'],
['An analyst averages region means equally despite unequal transaction counts. What needs review?','The intended weighting','Only the output labels','Only the index name','Only the CSV separator','An overall transaction mean requires weighting group means by their contributing counts.'],
['A summary has one row per region. Can it be treated as raw transactions?','No','Yes automatically','Only if values are numeric','Only if sorted','Aggregation changes grain and removes individual-row detail.'],
['An all-missing sum appears as zero under an aggregation. What should be checked?','The missing-value policy','Only the dtype label','Only row order','Only the report title','Unknown measurements should not be interpreted as known zero without a deliberate rule and appropriate aggregation options.']
],formal:[
['What does groupby define?','Partitions of rows by keys','Only column data types','A guaranteed causal comparison','A source file encoding','Grouping assigns rows to key-defined groups for further operations.'],
['Which aggregation reports group row count?','size','count of a nullable measure always','mean','sum of identifiers','size counts rows; measure count excludes nulls and sums are not row counts.'],
['What is named aggregation useful for?','Named summary meanings','Automatic data truth','Universal null imputation','Guaranteed random sampling','Naming each output measure makes its source and aggregation operation reviewable.'],
['A country field is missing for some sales. What should a regional summary decide?','Whether to retain an unknown group','That unknown means zero sales','That all missing rows are invalid','That parsing repaired every key','Missing-key inclusion affects population coverage and should be an explicit analytical choice.'],
['A shop has many item rows per order. What must an order-count summary use?','Distinct order identities','Only row size','Only price count','Only units sum','Row count at item grain is not order count; the entity definition must match the metric.'],
['A department compares two group averages with n=2 and n=2000. What should accompany them?','Their contributing counts','Only equal bar widths','Only the larger mean','Only group names','Counts expose different evidence sizes and help assess appropriate weighting and uncertainty.'],
['A categorical grouping shows empty categories unexpectedly. What option deserves explicit handling?','observed categories','Only memory alignment','Only file permissions','Only CSV quoting','Whether unused categories appear affects group output and should be specified for version-stable semantics.'],
['A pipeline groups before preserving raw records and then needs individual explanations. What was lost?','Row-level detail','Only column labels','Every numeric dtype','The concept of aggregation','Aggregates cannot generally reconstruct which individual observations produced them.'],
['An all-null revenue group totals zero and is called no revenue. What is unverified?','That missing means zero','That the group exists','That a sum ran','That output is numeric','Default aggregation behavior does not establish the business interpretation of absent measurements.'],
['A dashboard’s total changes after dropna=True is enabled on its key. Why might this happen?','Missing-key rows were excluded','Every duplicate was removed','All numbers were converted','The source acquired new records','Excluding missing grouping keys changes which rows contribute to the summary.']
]},
{id:'pd-vector',comps:['m2.c2'],title:'Create derived columns with aligned vectorized expressions',intro:'A sales analyst calculates line revenue from price and quantity. Vectorized expressions apply declared operations over columns and usually avoid Python-level row loops, but they still require aligned units, null rules and correct arithmetic.',sections:[['Express column operations directly','A derived column can be assigned from compatible Series expressions, such as quantity*unit_price. The result follows pandas index alignment. Boolean comparisons create masks that can identify a subset without looping through every row. Use parentheses around comparisons combined with & or | because operator precedence matters.','Vectorization describes how an operation is applied, not proof of speed or correctness for every workload. Object/string operations and temporary arrays have different costs. apply(axis=1) may be convenient but is not the same as a native vectorized numerical expression; benchmark only where performance matters.'],['Make exceptional values explicit','Division by zero, missing quantities and incompatible units need an agreed policy. Do not silently fill unknown costs with zero to produce favorable profits. Assignment should target the intended DataFrame explicitly, and derived-field definitions should be versioned when business rules change.','The fixture computes integer-cent line amounts and a eligibility mask, then handles a zero denominator with a nullable result. It is a local transformation example, not a complete tax/discount engine or a proof of optimal memory/performance.']],problem:'Derive line values and a ratio while preserving a no-opportunity state.',steps:['Multiply quantity and unit cents with aligned columns.','Build a mask using parenthesized comparisons.','Mask zero denominators before division.'],code:'import pandas as pd\ndf=pd.DataFrame({"qty":[2,0,3],"unit_cents":[100,500,50],"visits":[4,0,6]})\ndf["line_cents"]=df["qty"]*df["unit_cents"]\nmask=(df["qty"]>0)&(df["line_cents"]>=150)\nratio=df["qty"].div(df["visits"].where(df["visits"].ne(0)))\nprint(df["line_cents"].tolist())\nprint(mask.tolist())\nprint(ratio.isna().tolist())',expect:'[200, 0, 150]\n[True, False, True]\n[False, True, False]',limit:'Integer cents and the mask make this fixture reproducible. Real pricing, rounding and no-denominator interpretation need an approved business contract.',mistakes:['Vectorized code can be fast and still implement the wrong definition.','A missing denominator is not an observed ratio of zero.'],takeaways:['Prefer clear column expressions where appropriate.','Preserve alignment and exceptional-value policies.'],practice:[
['Which expression computes line amount from aligned columns?','df.qty*df.unit_cents','df.qty+df.unit_cents','df.qty/df.unit_cents always','df.qty.index','Multiplication combines the declared quantity and per-unit price for each aligned row.'],
['Which operator combines pandas Boolean masks elementwise?','& with parentheses','and for whole Series','A comma alone','Only string concatenation','Elementwise masks use & or | with explicit comparison parentheses, not Python scalar and/or.'],
['Does vectorized syntax prove the business formula is correct?','No','Yes automatically','Only for integer cents','Only on small tables','Execution style does not validate the metric’s units, scope or rules.'],
['A conversion denominator is zero. What should the derived ratio respect?','The no-opportunity policy','An automatic success value','A random fallback rate','Only the previous row','The undefined ratio needs explicit handling rather than an invented measurement.'],
['An expression adds dollars to cents without conversion. What is wrong?','Unit inconsistency','Only the Series dtype','Only the row order','Only vectorization syntax','Aligned positions do not make different units arithmetically compatible.'],
['A developer replaces every missing cost with zero. What must justify it?','The data/metric policy','Only code brevity','Only a faster runtime','Only a new column name','Missing costs are unknown values, so zero imputation changes meaning and potentially profitability.'],
['A row-wise apply is assumed faster than a numeric column expression. What is needed?','Representative measurement','Only a style preference','Only more comments','Only a screenshot','Performance depends on implementation and workload; convenience does not establish vectorized execution or speed.']
],formal:[
['What is a derived column?','A calculated field','A mandatory database key','Only a renamed source','A proof of causal effect','A derived column stores a transformation under an explicit definition.'],
['What determines arithmetic pairing between indexed Series?','Index alignment','Only equal length','Column display width','Alphabetical variable names','Supported pandas operations align index labels rather than relying solely on physical position.'],
['Why parenthesize comparisons in a combined mask?','To preserve intended precedence','To randomize rows','To delete nulls automatically','To force all values true','Parentheses make each comparison evaluate before elementwise Boolean combination.'],
['A retail calculation multiplies quantity by price per item. What must units support?','Consistent amount meaning','Only integer row ids','Only sorted products','Only equal column names','The formula is meaningful only if quantity and per-unit price refer to compatible units and business rules.'],
['A ratio produces infinity when opportunities are zero. What should be revised?','Exceptional cases','Only plot color','Only the file title','Only row sorting','A zero-denominator case must follow the defined metric policy and should not be presented as an ordinary observed rate.'],
['A vectorized calculation uses an outdated discount rule. What remains wrong?','The business definition','The concept of vectorization','All index labels','The existence of a Series','Fast bulk execution cannot correct an obsolete formula.'],
['A mask is created before rows are reindexed and reused later. What should be tested?','Selected identity/alignment','Only mask variable spelling','Only output font','Only memory estimate','The mask must still correspond to the intended rows after index changes.'],
['A notebook applies a Python function to each row and calls it native vectorization. What distinction matters?','Rows versus column ops','Only function-name length','Only whether output is numeric','Only the number of imports','apply(axis=1) invokes row-level behavior and is not automatically the same as a vectorized array operation.'],
['A pipeline derives profit after filling all missing revenue with zero. What should reviewers inspect?','Imputation and metric consequences','Only the profit column title','Only the package version string','Only the chart axis','Substantive fill choices change calculated outcomes and represented evidence.'],
['A very large vector expression allocates many temporaries. What must optimization consider?','Peak memory and readability','Only shortest source code','Only the final dtype','Only file compression','Vectorization can involve intermediate allocations, so performance work needs actual resource measurements and correctness checks.']
]},
{id:'pd-pivot',comps:['m2.c1','m2.c2'],title:'Pivot summaries without hiding duplicate combinations',intro:'A stock report may need one row per store and one column per product. Reshaping can change presentation without aggregation, or deliberately aggregate repeated combinations; those are different operations.',sections:[['pivot requires a unique cell identity','pivot uses selected index and column keys to place values into a wider shape. If multiple rows map to the same output cell, a simple pivot cannot choose a value and raises an error. This is useful evidence that the proposed grain is not unique.','pivot_table can aggregate duplicates using an explicit aggfunc. Its default aggregation may not be the intended business rule, so specify sum, mean or another justified operation. An aggregated result is not a faithful row-preserving reshape and should show the supporting counts where relevant.'],['Reshaping and derived columns have contracts','After pivoting, missing combinations can mean no observed row rather than a measured zero. A fill_value is a substantive display/analysis policy. Derive values such as line amounts before summarizing only when the row-level formula and aggregation match the metric.','The fixture intentionally contains duplicate store/product rows, checks that pivot rejects ambiguity and then sums with pivot_table. It demonstrates the selected rule, not a universal reason to aggregate every duplicate in operational data.']],problem:'Detect an ambiguous pivot and apply an explicitly chosen sum.',steps:['Identify the store/product cell keys.','Observe the simple pivot’s duplicate-cell failure.','Aggregate with a named sum rule and inspect the value.'],code:'import pandas as pd\ndf=pd.DataFrame({"store":["s1","s1"],"product":["p1","p1"],"units":[2,3]})\ntry:\n    df.pivot(index="store",columns="product",values="units")\nexcept ValueError:\n    print("duplicate cells")\np=df.pivot_table(index="store",columns="product",values="units",aggfunc="sum")\nprint(int(p.loc["s1","p1"]))',expect:'duplicate cells\n5',limit:'Sum is explicitly selected for these additive unit observations. Real duplicates may instead be retries or errors and require deduplication rather than aggregation.',mistakes:['pivot_table can hide duplication if the aggregation rule is not reviewed.','Missing store/product combinations are not automatically measured zeros.'],takeaways:['Check cell-key uniqueness before pivoting.','Distinguish reshaping from aggregation.'],practice:[
['What prevents a simple pivot from choosing a cell value?','Duplicate cell keys','Unique observations','A named value column','A nonempty index','Multiple records for one index/column combination make an unaggregated cell ambiguous.'],
['Which operation can aggregate repeated cell combinations?','pivot_table','pivot without aggregation','iloc','memory_usage','pivot_table supports an aggregation function to reduce repeated combinations deliberately.'],
['Should an aggregation rule be specified explicitly?','Yes','No, every default fits','Only for string keys','Only if rows are sorted','The chosen operation determines business meaning and should not be inherited blindly from a default.'],
['Two stock receipt rows refer to distinct deliveries of two and three units. Under an additive policy, what is their sum?','Five units','Two units','Three units','Six units','Distinct additive observations combine as 2+3=5 under the declared receipt definition.'],
['Two duplicate event deliveries represent one receipt. What should be decided before summing?','Logical-event identity','Only table orientation','Only product-name length','Only font size','Retries can duplicate one real event; aggregation would overcount unless the identity policy is resolved.'],
['A pivot has no observed store/product combination. What must a zero fill mean?','An explicit zero policy','Automatic measured zero','Proof of no demand','A guaranteed source fact','No row and a measured zero are different states unless the source/metric contract equates them.'],
['A wide report’s total differs from the source after aggregation. What should be audited?','Keys and aggregation','Only column widths','Only the report logo','Only row labels','Reshape/aggregation can alter coverage or combine rows, so reconciliation should target those transformations.']
],formal:[
['What does an unaggregated pivot require for each output cell?','A unique key combination','At least two observations','Only integer labels','A positive value','One output cell cannot represent multiple differing values without an explicit aggregation or selection rule.'],
['Which pivot_table argument defines how values combine?','aggfunc','dtype alone','iloc','deep','aggfunc specifies the reduction used for repeated groups/cells.'],
['Does a successful pivot_table prove source uniqueness?','No','Yes automatically','Only with numeric values','Only with sorted keys','Aggregation can reduce repeated source combinations while concealing their multiplicity.'],
['A payroll table has duplicate employee/month cells. What should happen before averaging?','Investigate the expected grain','Assume every duplicate is valid','Delete the largest payment','Only rename columns','Repeated cells may represent adjustments, errors or multiple valid records and require a business-grain decision.'],
['A sales pivot silently uses mean where the report needs total revenue. What is wrong?','The aggregation definition','The existence of row labels','The ability to store numbers','The use of a table','Mean and sum answer different questions; a valid operation can still implement the wrong metric.'],
['A warehouse fills all absent pivot cells with zero. What should be documented?','The missing-combination rule','Only the DataFrame shape','Only package import order','Only index spelling','Absent combinations may mean unobserved, unavailable or truly zero, depending on the contract.'],
['A pivot converts transaction rows to store summaries. What changed?','The analytical grain','Only display colors','Only the source filename','Nothing substantive','Aggregation produces store-level quantities and removes individual transaction detail.'],
['A report derives line amount as qty×price then sums by product. What needs validation?','Formula and aggregation','Only the final column title','Only the product-id format','Only the output sort','Correct group totals require meaningful row-level formulas, compatible units and additive semantics.'],
['A data team expects one measurement per sensor/time but pivot fails. What does the error help reveal?','A cell-key contract violation','Guaranteed sensor fraud','A missing Python interpreter','An impossible time axis','Duplicate sensor/time keys conflict with the proposed unique measurement grain.'],
['A reviewer wants to distinguish no observation from zero after a pivot. What should be preserved?','Missingness/coverage','Only the filled numeric table','Only column ordering','Only a rounded total','Preserving evidence state prevents display convenience from inventing measured zeros.']
]},
{id:'pd-merge',comps:['m3.c1'],title:'Merge tables with cardinality and match-coverage checks',intro:'A transaction table needs customer regions from a lookup. A merge can enrich records, multiply them or remove them, depending on keys, join type and lookup quality.',sections:[['Specify the relationship before combining','merge matches keys using a declared join type. A left join keeps left-side rows but can still expand them if the right key is repeated. Use validate="many_to_one" when many transactions should match at most one lookup row per customer. Other validation modes express one-to-one or one-to-many expectations.','indicator=True adds match provenance such as left_only and both. Check unmatched rows instead of assuming every retained record was enriched correctly. pandas can match null keys to null keys, unlike ordinary SQL equality joins; review null-key rules explicitly.'],['Reconcile counts and measures after joins','Before merging, state the grain and expected row count. After merging, verify identity, count and additive totals under the relationship contract. A many-to-many merge can create a Cartesian expansion within repeated keys; pandas performing it successfully does not make that expansion intended.','The fixture checks that a duplicated lookup violates many-to-one validation and then performs a corrected left merge with an unmatched customer. It does not resolve real duplicate identities or authorize disclosure of customer attributes.']],problem:'Reject a duplicate lookup and retain unmatched transactions visibly.',steps:['Assert the lookup relationship with validate.','Catch a relationship failure rather than ignoring it.','Merge a unique lookup and inspect match coverage.'],code:'import pandas as pd\nleft=pd.DataFrame({"customer":[1,2],"amount":[10,20]})\nbad=pd.DataFrame({"customer":[1,1],"region":["n","s"]})\ntry:\n    left.merge(bad,on="customer",how="left",validate="many_to_one")\nexcept pd.errors.MergeError:\n    print("invalid lookup")\nright=pd.DataFrame({"customer":[1],"region":["n"]})\nz=left.merge(right,on="customer",how="left",validate="many_to_one",indicator=True)\nprint(z["_merge"].astype(str).tolist())\nprint(int(z["amount"].sum()))',expect:"invalid lookup\n['both', 'left_only']\n30",limit:'The fixture verifies the stated relationship and source amount preservation for unique left rows. Real identity quality, null keys and field-access policy remain separate concerns.',mistakes:['A left join can still multiply left rows through duplicate right keys.','SQL-style null nonmatching cannot be assumed for pandas merge.'],takeaways:['Declare cardinality with validate.','Check match coverage and reconcile measures.'],practice:[
['Which validate mode fits many transactions to one customer lookup row?','many_to_one','many_to_many only','one_to_many always','outer','The right customer key should be unique while the left may repeat it across transactions.'],
['What does merge indicator reveal?','Match provenance','Every causal relationship','Only data types','Automatic key repair','The indicator distinguishes rows matched in both inputs from unmatched sides under the join.'],
['Can a left join increase row count?','Yes','No by definition','Only with missing columns','Only for string keys','Repeated right-side keys can match one left row multiple times.'],
['A customer lookup repeats a key with conflicting regions. What should a pipeline do?','Review the key contract','Choose a random region','Ignore expansion','Average region labels','Conflicting lookup identities violate the intended enrichment relationship and require explicit resolution.'],
['An inner merge removes unmatched orders. What must be evaluated?','Population loss','Only faster execution','Only table color','Only filename order','Inner matching can exclude business entities and alter totals or denominators.'],
['A dataframe has missing join keys on both sides. What pandas behavior needs review?','Null keys can match','Nulls always behave like SQL equality','Every null is dropped','All rows become unique','pandas merge can pair null keys, which differs from ordinary SQL NULL equality semantics.'],
['Revenue doubles after enrichment without new orders. What is a likely issue?','Unintended join multiplicity','Guaranteed revenue growth','Only rounding drift','Automatic missing-value repair','Duplicate key relationships can repeat monetary measures and inflate totals.']
],formal:[
['What does merge validate check?','Declared key relationship','Truth of every attribute','Universal source completeness','All privacy permissions','Validation tests uniqueness/cardinality expectations for the specified merge relationship.'],
['What does a left join preserve in membership?','All left-side keys/rows at least once','Exactly the same row count always','Only matched rows','Only right-side rows','Left membership remains, but multiple matches can expand row count.'],
['Which merge type can restrict output to matched keys?','inner','left always','outer always','concat','An inner merge returns matches, so unmatched entities may disappear.'],
['A financial enrichment has unique lookup keys but many unmatched accounts. What still matters?','Match coverage','Only cardinality success','Only dtype memory','Only source filename','Uniqueness does not guarantee completeness of matching; unmatched accounts may lack required context.'],
['A transaction key repeats on both inputs. What can a many-to-many merge produce?','Combinations within each key','Automatic deduplication','Only one selected row','A guaranteed validation error','Each matching row on one side can combine with each matching row on the other, expanding output.'],
['A pandas merge is ported to SQL and null-key results change. Why is this plausible?','Null matching differs','SQL cannot join tables','pandas has no missing values','Only output sorting differs','pandas can match null keys, whereas ordinary SQL equality does not match NULL to NULL.'],
['A developer removes validate because it rejects bad lookup data. What is the cost?','Loss of a relationship safeguard','Guaranteed corrected source data','A repaired key meaning','Automatic accurate totals','Disabling the check hides a contract failure rather than resolving the duplicate relationship.'],
['An analyst checks only final row count after merging. What additional check targets missing identities?','Match/key coverage','Only final memory size','Only output file extension','Only column widths','The same count can hide removed and multiplied entities, so identity and match checks are necessary.'],
['A customer lookup contains private fields unnecessary for a regional report. What should be selected?','Authorized needed fields','Every available source field','Only the longest text values','Random attributes','Enrichment should respect purpose and access scope, not expose all fields just because merging is possible.'],
['A report’s revenue is unchanged after a join. Does that alone prove entity correctness?','No, multiple errors may offset','Yes, totals are complete proof','Only for integer amounts','Only for left joins','Aggregate reconciliation is useful but can miss compensating identity, coverage or duplication errors.']
]},
{id:'pd-concat',comps:['m3.c2'],title:'Concatenate extracts while preserving source and schema meaning',intro:'Monthly extracts often need to be stacked into one table. Concatenation combines axes; it does not automatically prove compatible schemas, eliminate duplicates or align business periods.',sections:[['Choose the axis and schema policy','concat with axis=0 stacks rows and aligns columns by name. With an outer schema union, a column absent from one input becomes missing for those rows. An inner schema intersection can silently remove fields not shared by every input. Decide which schema policy is valid before stacking.','ignore_index=True creates a new sequential index but does not remove duplicate business records. keys can retain source provenance in a hierarchical index, or an explicit source column can record the origin. Avoid repeatedly appending tiny pieces inside loops when one concatenation of collected frames is appropriate.'],['Check overlap and version changes','Monthly extracts may overlap at period boundaries, arrive as revised snapshots or use changed field definitions. Verify business keys, units, currency and source versions before counting rows as new observations. A duplicate key may be a retry, a correction or a valid repeated event depending on grain.','The fixture concatenates two differently shaped extracts and shows a missing column and a repeated order id. It preserves those facts for review rather than declaring the combined result clean because its new index is unique.']],problem:'Stack extracts and expose both schema gaps and repeated business ids.',steps:['Create two synthetic extracts with one shared order id.','Concatenate with an explicit new positional index.','Inspect missing schema values and business-key duplicates.'],code:'import pandas as pd\na=pd.DataFrame({"order":[1,2],"amount":[10,20]})\nb=pd.DataFrame({"order":[2,3],"amount":[20,30],"source":["revised","new"]})\nz=pd.concat([a,b],ignore_index=True,sort=False)\nprint(z["order"].tolist())\nprint(int(z["source"].isna().sum()))\nprint(int(z["order"].duplicated().sum()))',expect:'[1, 2, 2, 3]\n2\n1',limit:'A repeated order id is only a flag here. The correct correction/deduplication policy depends on whether the extracts are events, snapshots or revisions.',mistakes:['A fresh RangeIndex does not make business identities unique.','Schema union can introduce missing fields even when concatenation succeeds.'],takeaways:['Separate stacking from deduplication.','Keep source provenance and review schema overlap.'],practice:[
['What does concat(axis=0) primarily do?','Stack aligned rows','Match customer lookup keys','Remove every duplicate','Calculate a group mean','Row concatenation combines input rows while aligning the column axis.'],
['Does ignore_index=True deduplicate business ids?','No','Yes universally','Only for integers','Only for strings','It creates positional labels but leaves repeated business records intact.'],
['What can schema union introduce?','Missing fields for some rows','Guaranteed complete observations','Automatic unit conversion','Mandatory key uniqueness','Columns absent from an input become missing in that input’s contributed rows.'],
['Two monthly exports overlap on the closing day. What should be checked?','Business-key/time overlap','Only filename length','Only file compression','Only chart orientation','Overlapping extracts can duplicate the same logical event or entity snapshot.'],
['An inner schema intersection drops a tax column. What must be reviewed?','Field-loss acceptability','Only output row order','Only index name','Only memory formatting','Intersecting schemas can remove relevant information and change downstream calculations.'],
['A revised snapshot repeats an order id with a corrected amount. What is needed before deduplication?','A revision-precedence policy','A random first-row choice','Only ignore_index=True','Only a new column color','Corrections need a documented version/authority rule rather than arbitrary duplicate removal.'],
['A combined table lacks any source marker. What becomes harder?','Tracing source origin','Counting final rows','Reading column names','Computing one sum','Without origin/version information, mismatches and corrections are harder to reconcile.']
],formal:[
['Which operation stacks tables rather than matching relational keys?','concat','merge on customer id','groupby sum','pivot_table mean','Concatenation combines along an axis; merging matches key relationships.'],
['What does ignore_index change?','The concatenation-axis labels','The business records themselves','Every duplicated event','All currency units','It replaces axis labels with a new sequence and does not validate or change business identity.'],
['What is source provenance useful for after stacking?','Tracing origin and revision','Proving causality','Removing access rules','Guaranteeing every value true','Origin/version information supports reconciliation and reproducibility of combined extracts.'],
['An analyst stacks two copies of the same weekly file. What does concat do by default?','Retain both sets of rows','Detect and discard one file','Average every duplicate','Reject identical file content','Concatenation does not infer logical source duplication or perform automatic deduplication.'],
['A source column is absent from one of two extracts. Under outer column union, what happens?','Those rows receive missing values','The column always disappears','All rows become invalid','The absent values become zero','Union aligns available columns and represents absent fields as missing.'],
['A new file changes amount units but keeps the column name. What should prevent blind stacking?','Schema/semantic contract checks','Only matching field spelling','Only equal file sizes','Only a new RangeIndex','Matching names do not establish compatible units or definitions.'],
['A reporting script concatenates frames in a loop and assumes speed scales well. What is appropriate?','Measure bulk concat','Assume no temporary copies','Delete validation checks','Replace ids with positions','Repeated concatenation can copy data repeatedly; collect pieces and concatenate once where suitable, then benchmark.'],
['A final index is unique after ignore_index. What is still unverified?','Business-key uniqueness','That row labels exist','That rows were combined','That a RangeIndex was created','Index relabeling does not prove that orders, users or events are unique.'],
['A schema intersection removes every nonshared field. What should documentation state?','The deliberate field-loss policy','That all source information survived','That units were converted','That duplicates vanished','Selecting only shared columns sacrifices noncommon information and needs an explicit purpose.'],
['A data team needs to trace each concatenated row to its month. Which design supports it?','Explicit source labels/keys','Only a new sequential index','Only sorted amounts','Only deduplicated names','Provenance can be stored in a source column or concat keys rather than inferred from final row positions.']
]},
{id:'pd-reshape',comps:['m3.c1','m3.c2'],title:'Reshape long and wide data with reconciliation checks',intro:'Survey responses may arrive one column per question, while analysis needs one row per respondent/question. A reshape changes representation and can multiply rows without creating new independent respondents.',sections:[['melt makes variable names into values','melt keeps id_vars as identifiers and turns selected value_vars columns into a variable column and a value column. A respondent with three selected questions can contribute three long rows. Those are repeated measures from one entity, not three independent people.','Specify variable/value names and which columns participate. Accidental inclusion of metadata as a value variable can create meaningless measurements. Preserve enough identity to trace each long row to an original cell and to distinguish repeated question versions or occasions.'],['Validate the round trip rather than assuming it','If respondent/question combinations are unique, pivot can reconstruct the selected wide representation. A round trip needs suitable keys, labels, dtype handling and missing-value conventions. It is not a universal proof that every source attribute was retained, because excluded columns and duplicated identities can be lost or ambiguous.','The fixture melts two question columns for two respondents, counts both rows and unique people, and pivots back after checking uniqueness. This demonstrates a controlled reshape rather than a relational join or an increase in sample information.']],problem:'Reshape a small survey to long form and reconstruct its selected cells.',steps:['Declare respondent id and the two question columns.','Melt to one row per respondent/question.','Verify cell-key uniqueness and pivot back for comparison.'],code:'import pandas as pd\nwide=pd.DataFrame({"person":["a","b"],"q1":[1,2],"q2":[3,4]})\nlong=wide.melt(id_vars="person",value_vars=["q1","q2"],var_name="question",value_name="answer")\nprint(len(long),long["person"].nunique())\nprint(bool(long.duplicated(["person","question"]).any()))\nback=long.pivot(index="person",columns="question",values="answer")\nprint(back.loc["a"].tolist())',expect:'4 2\nFalse\n[1, 3]',limit:'The round trip preserves these selected unique cells. It does not preserve unspecified metadata or make repeated survey answers independent observations.',mistakes:['More long-format rows do not mean more distinct respondents.','Omitted metadata is not recovered automatically by pivoting back.'],takeaways:['Choose stable cell identities for reshaping.','Reconcile entity counts, cell uniqueness and selected values.'],practice:[
['What does melt create from selected value columns?','Variable/value rows','A customer-key lookup','A unique person per cell','An automatic average','melt converts selected wide columns into variable names and corresponding values in long form.'],
['Which melt argument preserves identifier columns?','id_vars','value_name only','aggfunc','validate="one_to_one"','id_vars lists columns retained as identifiers in the long output.'],
['Two people answer two questions. How many long response rows can result?','Four','Two','One','Eight','Each selected person/question cell becomes a long row, yielding two times two observations.'],
['A researcher treats four response rows as four independent people. What is wrong?','Repeated-person grain','Only question spelling','Only output sorting','Only answer dtype','Multiple question responses can belong to the same person and are not additional independent respondents.'],
['A pivot back fails because person/question repeats. What should be reviewed?','The cell-key contract','Only display width','Only the index title','Only integer encoding','Duplicate output-cell identities require an additional key or a justified aggregation/selection policy.'],
['Metadata was excluded from melt and is absent after reconstruction. What is expected?','Selected cells alone were preserved','Every source field was guaranteed','A causal effect was removed','All rows were deduplicated','A controlled reshape round trip only preserves the information included in its specified mapping.'],
['A long table will be merged with respondent attributes. What relationship should be checked?','Many responses to one respondent','Many-to-many by default','One respondent per answer value','Only equal row counts','The attribute lookup should match one row per respondent while long responses can repeat respondents.']
],formal:[
['What is long-format grain in a person/question survey?','One person/question cell','Always one person only','Always one question only','A whole dataset in one row','Long format separates selected measurements into rows identified by entity and variable.'],
['What must an unaggregated reverse pivot have?','Unique output-cell keys','Only equal column lengths','A positive answer value','At least ten respondents','A single output cell must correspond to one value unless an explicit aggregation is intended.'],
['Does reshaping necessarily add new information?','No','Yes for every new row','Only if values are numeric','Only if the index is reset','A reshape can reorganize the same cells without adding independent observations or new measurements.'],
['A school melts test subjects into long rows. What should remain available?','Student/subject identity','Only the score value','Only row position','Only a chart color','Stable identifiers preserve which student/subject cell each response represents.'],
['A long table repeats a respondent ten times. What does a respondent-level count need?','Distinct respondent ids','Only total row count','Only answer count','Only the number of columns','Repeated measures are not distinct people; entity-level counts must follow the entity grain.'],
['A wide table includes salary and age but melt includes an internal note accidentally. What failed?','Value-column selection','The ability to concatenate','Only index sorting','Only decimal precision','Choosing value_vars deliberately prevents unrelated metadata from becoming purported measurements.'],
['A reshape round trip returns equal selected values. What remains outside that evidence?','Excluded source metadata','The compared selected cells','The tested respondent ids','That a pivot executed','A targeted equality check does not establish preservation of information that was never included.'],
['A survey has repeated waves with the same person/question keys. What key may be missing?','The observation wave','Only a longer name string','Only a currency code','Only the maximum answer','Repeated occasions require another identity dimension to make each cell unique.'],
['A response table joins to a respondent lookup with duplicate respondent keys. What risk appears?','Multiplication of long rows','Automatic respondent deduplication','Guaranteed response averaging','A preserved unique cell contract','Nonunique lookup matches can expand each response and corrupt the intended long-format grain.'],
['A reviewer checks only long row count after melt. What else should be tested?','Cell identity and values','Only the output filename','Only the font choice','Only the number of imports','Counts alone cannot show whether the right source cells and identifiers survived the reshape.']
]}
];
module.exports=course('pandas-fundamentals',specs,['indexing','basics','groupby','reshaping','merging','missing_data']);
